import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    A = int(data[0])
    B = int(data[1])
    grid = data[2:2 + A]

    def get_rotations(piece):
        rows = len(piece)
        cols = len(piece[0])
        rotations = set()

        current = [list(row) for row in piece]
        for _ in range(2):
            rotated = tuple(tuple(current[j][rows - 1 - i] for j in range(cols)) for i in range(rows))
            rotations.add(rotated)
            current = [list(row) for row in rotated]
        return rotations

    good_count = 0
    best_X = None
    best_Y = None

    for X in range(1, A + 1):
        if A % X != 0:
            continue
        for Y in range(1, B + 1):
            if B % Y != 0:
                continue

            num_pieces = (A // X) * (B // Y)
            pieces_set = set()
            is_good = True

            for r in range(0, A, X):
                for c in range(0, B, Y):
                    piece = []
                    for dr in range(X):
                        row_chars = []
                        for dc in range(Y):
                            row_chars.append(grid[r + dr][c + dc])
                        piece.append("".join(row_chars))

                    rotations = get_rotations(piece)
                    if rotations & pieces_set:
                        is_good = False
                        break
                    pieces_set |= rotations

                if not is_good:
                    break

            if is_good:
                good_count += 1
                if best_X is None:
                    best_X, best_Y = X, Y
                else:
                    curr_area = X * Y
                    best_area = best_X * best_Y
                    if curr_area < best_area or (curr_area == best_area and X < best_X):
                        best_X, best_Y = X, Y

    print(good_count)
    print(f"{best_X} {best_Y}")

if __name__ == "__main__":
    main()
